-- Endurecimento pré-piloto: âncoras anatômicas confiáveis e origem FHIR escopada.

CREATE TABLE public.atlas_malhas (
  atlas text NOT NULL CHECK (atlas IN ('bp3d-m','hra-f')),
  versao text NOT NULL,
  malha text NOT NULL,
  sistema text NOT NULL,
  lateralidade text CHECK (lateralidade IN ('left','right')),
  estrutura text,
  PRIMARY KEY (atlas,versao,malha)
);
ALTER TABLE public.atlas_malhas ENABLE ROW LEVEL SECURITY;
CREATE POLICY atlas_malhas_leitura_authenticated ON public.atlas_malhas
  FOR SELECT TO authenticated USING (true);
REVOKE ALL ON TABLE public.atlas_malhas FROM PUBLIC, anon, authenticated;
GRANT SELECT ON TABLE public.atlas_malhas TO authenticated;

