ALTER TABLE public.importacoes_fhir ADD COLUMN sistema_origem text NOT NULL DEFAULT 'legado';
ALTER TABLE public.importacoes_fhir ALTER COLUMN sistema_origem DROP DEFAULT;
ALTER TABLE public.importacoes_fhir ADD CONSTRAINT importacoes_fhir_sistema_origem_check
  CHECK (sistema_origem=lower(btrim(sistema_origem)) AND char_length(sistema_origem) BETWEEN 1 AND 200);

ALTER TABLE public.paciente_fhir ADD COLUMN sistema_origem text NOT NULL DEFAULT 'legado';
ALTER TABLE public.paciente_fhir ALTER COLUMN sistema_origem DROP DEFAULT;
ALTER TABLE public.paciente_fhir DROP CONSTRAINT paciente_fhir_pkey;
ALTER TABLE public.paciente_fhir ADD CONSTRAINT paciente_fhir_sistema_origem_check
  CHECK (sistema_origem=lower(btrim(sistema_origem)) AND char_length(sistema_origem) BETWEEN 1 AND 200);
ALTER TABLE public.paciente_fhir ADD CONSTRAINT paciente_fhir_pkey
  PRIMARY KEY (unidade_id,sistema_origem,fhir_id);

DROP INDEX public.achados_unidade_fhir_id_uidx;
ALTER TABLE public.achados ADD COLUMN sistema_origem text;
UPDATE public.achados SET sistema_origem='legado' WHERE origem='fhir';
ALTER TABLE public.achados ADD CONSTRAINT achados_sistema_origem_check CHECK (
  (origem='fhir' AND sistema_origem IS NOT NULL AND sistema_origem=lower(btrim(sistema_origem))
    AND char_length(sistema_origem) BETWEEN 1 AND 200)
  OR (origem<>'fhir' AND (sistema_origem IS NULL OR
    (sistema_origem=lower(btrim(sistema_origem)) AND char_length(sistema_origem) BETWEEN 1 AND 200)))
);
CREATE UNIQUE INDEX achados_unidade_origem_fhir_id_uidx
  ON public.achados(unidade_id,sistema_origem,fhir_id)
  WHERE origem='fhir' AND fhir_id IS NOT NULL;

DROP INDEX public.eventos_clinicos_unidade_fhir_id_uidx;
ALTER TABLE public.eventos_clinicos ADD COLUMN sistema_origem text NOT NULL DEFAULT 'legado';
ALTER TABLE public.eventos_clinicos ALTER COLUMN sistema_origem DROP DEFAULT;
ALTER TABLE public.eventos_clinicos ADD CONSTRAINT eventos_clinicos_sistema_origem_check
  CHECK (sistema_origem=lower(btrim(sistema_origem)) AND char_length(sistema_origem) BETWEEN 1 AND 200);
CREATE UNIQUE INDEX eventos_clinicos_unidade_origem_fhir_id_uidx
  ON public.eventos_clinicos(unidade_id,sistema_origem,fhir_id);

CREATE FUNCTION public.normalizar_ancora(p_ancora jsonb, p_sexo public.sexo)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = ''
AS $$
DECLARE esperado text; sistema_catalogo text; lateralidade_catalogo text; estrutura_catalogo text;
BEGIN
  IF p_ancora IS NULL THEN RETURN NULL; END IF;
  esperado := CASE p_sexo WHEN 'feminino' THEN 'hra-f' WHEN 'masculino' THEN 'bp3d-m' ELSE NULL END;
  IF esperado IS NULL OR jsonb_typeof(p_ancora) IS DISTINCT FROM 'object'
    OR NULLIF(p_ancora->>'atlas','') IS NULL
    OR NULLIF(p_ancora->>'atlas_versao','') IS NULL
    OR NULLIF(p_ancora->>'malha','') IS NULL
    OR p_ancora->>'atlas' IS DISTINCT FROM esperado THEN
    RAISE EXCEPTION 'Âncora anatômica inválida' USING ERRCODE='22023';
  END IF;
  SELECT m.sistema,m.lateralidade,m.estrutura
    INTO sistema_catalogo,lateralidade_catalogo,estrutura_catalogo
    FROM public.atlas_malhas AS m
    WHERE m.atlas=p_ancora->>'atlas' AND m.versao=p_ancora->>'atlas_versao'
      AND m.malha=p_ancora->>'malha';
  IF NOT FOUND THEN RAISE EXCEPTION 'Âncora anatômica inválida' USING ERRCODE='22023'; END IF;
  RETURN jsonb_set(
    jsonb_set(
      jsonb_set(p_ancora,'{sistema}',to_jsonb(sistema_catalogo),true),
      '{lateralidade}',COALESCE(to_jsonb(lateralidade_catalogo),'null'::jsonb),true
    ),
    '{estrutura}',COALESCE(to_jsonb(estrutura_catalogo),'null'::jsonb),true
  );
END
$$;
REVOKE ALL ON FUNCTION public.normalizar_ancora(jsonb,public.sexo) FROM PUBLIC, anon, authenticated;

CREATE OR REPLACE FUNCTION public.registrar_achado(
  p_paciente uuid, p_ancora jsonb, p_cid10 text, p_categoria public.categoria_achado,
  p_lado public.lado_achado, p_status public.status_achado, p_inicio date,
  p_observacao text, p_substitui uuid DEFAULT NULL
)
RETURNS uuid LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = ''
AS $$
DECLARE
  usuario uuid := auth.uid(); unidade uuid := public.minha_unidade(); esp text;
  sigilo public.nivel_sigilo := 'normal'; novo uuid; sexo_paciente public.sexo;
  ancora_validada jsonb; lateralidade_catalogo text;
BEGIN
  IF usuario IS NULL OR unidade IS NULL THEN RAISE EXCEPTION 'Perfil ausente' USING ERRCODE='42501'; END IF;
  SELECT p.especialidade INTO esp FROM public.perfis AS p WHERE p.id=usuario;
  IF NOT EXISTS (
    SELECT 1 FROM public.vinculos AS v WHERE v.paciente_id=p_paciente AND v.unidade_id=unidade
      AND v.desde<=CURRENT_DATE AND (v.ate IS NULL OR v.ate>CURRENT_DATE)
  ) THEN
    INSERT INTO public.auditoria(autor_id,unidade_id,paciente_id,acao)
      VALUES(usuario,unidade,NULL,'acesso_negado');
    RETURN NULL;
  END IF;
  IF p_ancora IS NOT NULL THEN
    SELECT p.sexo INTO sexo_paciente FROM public.pacientes AS p WHERE p.id=p_paciente;
    ancora_validada := public.normalizar_ancora(p_ancora,sexo_paciente);
    lateralidade_catalogo := ancora_validada->>'lateralidade';
    -- só contradição explícita: malha sem lado (pele inteira, órgão mediano) aceita o lado clínico informado
    IF (lateralidade_catalogo='left' AND p_lado='direito') OR
       (lateralidade_catalogo='right' AND p_lado='esquerdo') THEN
      RAISE EXCEPTION 'Âncora anatômica inválida' USING ERRCODE='22023';
    END IF;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.cid10 AS c WHERE c.codigo=p_cid10) THEN
    RAISE EXCEPTION 'CID-10 inexistente' USING ERRCODE='22023';
  END IF;
  SELECT 'restrito'::public.nivel_sigilo INTO sigilo FROM public.cid10_sigilo AS s
    WHERE p_cid10 LIKE s.prefixo || '%' ORDER BY length(s.prefixo) DESC LIMIT 1;
  sigilo := COALESCE(sigilo,'normal'::public.nivel_sigilo);
  IF p_substitui IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.achados AS a WHERE a.id=p_substitui AND a.paciente_id=p_paciente AND a.unidade_id=unidade
  ) THEN RAISE EXCEPTION 'Achado substituído indisponível' USING ERRCODE='42501'; END IF;
  INSERT INTO public.achados(paciente_id,autor_id,unidade_id,especialidade,ancora,cid10,categoria,lado,status,
    nivel_sigilo,inicio,observacao,substitui_id)
  VALUES(p_paciente,usuario,unidade,esp,ancora_validada,p_cid10,p_categoria,p_lado,p_status,
    sigilo,p_inicio,p_observacao,p_substitui) RETURNING id INTO novo;
  INSERT INTO public.auditoria(autor_id,unidade_id,paciente_id,acao)
    VALUES(usuario,unidade,p_paciente,'registrar_achado');
  RETURN novo;
END
$$;
REVOKE ALL ON FUNCTION public.registrar_achado(uuid,jsonb,text,public.categoria_achado,
  public.lado_achado,public.status_achado,date,text,uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.registrar_achado(uuid,jsonb,text,public.categoria_achado,
  public.lado_achado,public.status_achado,date,text,uuid) TO authenticated;

DROP FUNCTION public.iniciar_importacao(text,int);
CREATE FUNCTION public.iniciar_importacao(p_arquivo text,p_recursos int,p_sistema_origem text)
RETURNS uuid LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = ''
AS $$
DECLARE usuario uuid:=auth.uid(); unidade uuid:=public.minha_unidade(); novo uuid; origem text;
BEGIN
  IF usuario IS NULL OR unidade IS NULL THEN RETURN NULL; END IF;
  IF NOT public.eh_admin() THEN
    INSERT INTO public.auditoria(autor_id,unidade_id,paciente_id,acao)
      VALUES(usuario,unidade,NULL,'acesso_negado');
    RETURN NULL;
  END IF;
  origem:=lower(btrim(p_sistema_origem));
  IF p_recursos IS NULL OR p_recursos<0 OR NULLIF(btrim(p_arquivo),'') IS NULL
    OR origem IS NULL OR char_length(origem) NOT BETWEEN 1 AND 200 THEN
    RAISE EXCEPTION 'Metadados de importação inválidos' USING ERRCODE='22023';
  END IF;
  INSERT INTO public.importacoes_fhir(autor_id,unidade_id,arquivo,recursos,sistema_origem)
    VALUES(usuario,unidade,btrim(p_arquivo),p_recursos,origem) RETURNING id INTO novo;
  INSERT INTO public.auditoria(autor_id,unidade_id,paciente_id,acao)
    VALUES(usuario,unidade,NULL,'iniciar_importacao');
  RETURN novo;
END
$$;
REVOKE ALL ON FUNCTION public.iniciar_importacao(text,int,text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.iniciar_importacao(text,int,text) TO authenticated;

CREATE OR REPLACE FUNCTION public.importar_paciente_fhir(
  p_importacao uuid,p_fhir_id text,p_cns text,p_nome text,p_sexo public.sexo,p_nascimento date
)
RETURNS uuid LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = ''
AS $$
DECLARE usuario uuid:=auth.uid(); unidade uuid:=public.minha_unidade(); paciente uuid; cns_limpo text;
  paciente_mapeado uuid; cns_mapeado text; sistema_importacao text;
BEGIN
  p_fhir_id:=NULLIF(btrim(p_fhir_id),'');
  IF usuario IS NULL OR unidade IS NULL THEN RETURN NULL; END IF;
  IF NOT public.eh_admin() OR NOT EXISTS (
    SELECT 1 FROM public.importacoes_fhir AS i WHERE i.id=p_importacao AND i.autor_id=usuario
      AND i.unidade_id=unidade AND i.concluido_em IS NULL
  ) THEN
    INSERT INTO public.auditoria(autor_id,unidade_id,paciente_id,acao) VALUES(usuario,unidade,NULL,'acesso_negado');
    RETURN NULL;
  END IF;
  SELECT i.sistema_origem INTO sistema_importacao FROM public.importacoes_fhir AS i WHERE i.id=p_importacao;
  IF p_fhir_id IS NULL OR NULLIF(btrim(p_nome),'') IS NULL THEN
    RAISE EXCEPTION 'Paciente FHIR inválido' USING ERRCODE='22023';
  END IF;
  cns_limpo:=NULLIF(btrim(p_cns),'');
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext(unidade::text),
    pg_catalog.hashtext(sistema_importacao||':'||p_fhir_id));
  SELECT pf.paciente_id,p.cns INTO paciente_mapeado,cns_mapeado FROM public.paciente_fhir AS pf
    JOIN public.pacientes AS p ON p.id=pf.paciente_id
    WHERE pf.unidade_id=unidade AND pf.sistema_origem=sistema_importacao AND pf.fhir_id=p_fhir_id;
  IF paciente_mapeado IS NOT NULL AND cns_limpo IS NOT NULL AND cns_limpo IS DISTINCT FROM cns_mapeado THEN
    RAISE EXCEPTION 'Recurso Patient inconsistente' USING ERRCODE='22023';
  END IF;
  paciente:=paciente_mapeado;
  IF paciente IS NULL AND cns_limpo IS NOT NULL THEN
    SELECT p.id INTO paciente FROM public.pacientes AS p WHERE p.cns=cns_limpo;
  END IF;
  IF paciente IS NULL THEN
    INSERT INTO public.pacientes(nome,cns,sexo,data_nascimento)
      VALUES(btrim(p_nome),cns_limpo,p_sexo,p_nascimento) ON CONFLICT DO NOTHING RETURNING id INTO paciente;
    IF paciente IS NULL AND cns_limpo IS NOT NULL THEN
      SELECT p.id INTO paciente FROM public.pacientes AS p WHERE p.cns=cns_limpo;
    END IF;
  END IF;
  IF paciente IS NULL THEN
    INSERT INTO public.auditoria(autor_id,unidade_id,paciente_id,acao) VALUES(usuario,unidade,NULL,'acesso_negado');
    RETURN NULL;
  END IF;
  INSERT INTO public.paciente_fhir(unidade_id,sistema_origem,fhir_id,paciente_id)
    VALUES(unidade,sistema_importacao,p_fhir_id,paciente) ON CONFLICT(unidade_id,sistema_origem,fhir_id) DO NOTHING
    RETURNING paciente_id INTO paciente_mapeado;
  IF paciente_mapeado IS NULL THEN
    SELECT pf.paciente_id INTO paciente_mapeado FROM public.paciente_fhir AS pf
      WHERE pf.unidade_id=unidade AND pf.sistema_origem=sistema_importacao AND pf.fhir_id=p_fhir_id;
  END IF;
  IF paciente_mapeado IS NULL THEN
    INSERT INTO public.auditoria(autor_id,unidade_id,paciente_id,acao) VALUES(usuario,unidade,NULL,'acesso_negado');
    RETURN NULL;
  END IF;
  IF paciente_mapeado<>paciente THEN RAISE EXCEPTION 'Recurso Patient inconsistente' USING ERRCODE='22023'; END IF;
  INSERT INTO public.vinculos(paciente_id,unidade_id,motivo,origem,criado_por,desde)
    VALUES(paciente,unidade,'Importação FHIR','importacao',usuario,CURRENT_DATE)
    ON CONFLICT(paciente_id,unidade_id,desde) DO UPDATE SET motivo=EXCLUDED.motivo,
      origem=EXCLUDED.origem,criado_por=EXCLUDED.criado_por,ate=NULL;
  INSERT INTO public.auditoria(autor_id,unidade_id,paciente_id,acao)
    VALUES(usuario,unidade,paciente,'importar_paciente_fhir');
  RETURN paciente;
END
$$;
REVOKE ALL ON FUNCTION public.importar_paciente_fhir(uuid,text,text,text,public.sexo,date) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.importar_paciente_fhir(uuid,text,text,text,public.sexo,date) TO authenticated;

DROP FUNCTION public.importar_condicao_fhir(uuid,uuid,text,text,jsonb,public.status_achado,date);
CREATE FUNCTION public.importar_condicao_fhir(
  p_importacao uuid,p_paciente uuid,p_fhir_id text,p_cid10 text,p_ancora jsonb,
  p_status public.status_achado,p_inicio date,p_verification_status text DEFAULT 'confirmed'
)
RETURNS uuid LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = ''
AS $$
DECLARE usuario uuid:=auth.uid(); unidade uuid:=public.minha_unidade(); existente public.achados;
  novo uuid; sigilo public.nivel_sigilo; sistema_importacao text; sexo_paciente public.sexo;
  ancora_validada jsonb; lateralidade_catalogo text; lado_catalogo public.lado_achado:='nao_se_aplica';
BEGIN
  p_fhir_id:=NULLIF(btrim(p_fhir_id),'');
  IF usuario IS NULL OR unidade IS NULL THEN RETURN NULL; END IF;
  SELECT i.sistema_origem INTO sistema_importacao FROM public.importacoes_fhir AS i WHERE i.id=p_importacao
    AND i.autor_id=usuario AND i.unidade_id=unidade AND i.concluido_em IS NULL;
  IF NOT public.eh_admin() OR sistema_importacao IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.vinculos AS v WHERE v.paciente_id=p_paciente AND v.unidade_id=unidade
      AND v.desde<=CURRENT_DATE AND (v.ate IS NULL OR v.ate>CURRENT_DATE)
  ) THEN
    INSERT INTO public.auditoria(autor_id,unidade_id,paciente_id,acao) VALUES(usuario,unidade,NULL,'acesso_negado');
    RETURN NULL;
  END IF;
  IF p_fhir_id IS NULL OR p_verification_status IN ('entered-in-error','refuted') THEN
    RAISE EXCEPTION 'Condição FHIR inválida' USING ERRCODE='22023';
  END IF;
  SELECT a.* INTO existente FROM public.achados AS a WHERE a.unidade_id=unidade AND a.sistema_origem=sistema_importacao
    AND a.origem='fhir' AND a.fhir_id=p_fhir_id;
  IF FOUND THEN
    IF existente.paciente_id=p_paciente THEN
      INSERT INTO public.auditoria(autor_id,unidade_id,paciente_id,acao)
        VALUES(usuario,unidade,p_paciente,'importar_condicao_fhir');
      RETURN existente.id;
    END IF;
    INSERT INTO public.auditoria(autor_id,unidade_id,paciente_id,acao) VALUES(usuario,unidade,NULL,'acesso_negado');
    RETURN NULL;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.cid10 AS c WHERE c.codigo=p_cid10) THEN
    RAISE EXCEPTION 'CID-10 inexistente' USING ERRCODE='22023';
  END IF;
  IF p_ancora IS NOT NULL THEN
    SELECT p.sexo INTO sexo_paciente FROM public.pacientes AS p WHERE p.id=p_paciente;
    ancora_validada:=public.normalizar_ancora(p_ancora,sexo_paciente);
    lateralidade_catalogo:=ancora_validada->>'lateralidade';
    IF lateralidade_catalogo='left' THEN lado_catalogo:='esquerdo';
    ELSIF lateralidade_catalogo='right' THEN lado_catalogo:='direito'; END IF;
  END IF;
  SELECT 'restrito'::public.nivel_sigilo INTO sigilo FROM public.cid10_sigilo AS s
    WHERE p_cid10 LIKE s.prefixo || '%' ORDER BY length(s.prefixo) DESC LIMIT 1;
  sigilo:=COALESCE(sigilo,'normal'::public.nivel_sigilo);
  INSERT INTO public.achados(paciente_id,autor_id,unidade_id,especialidade,ancora,cid10,categoria,
    lado,status,nivel_sigilo,inicio,origem,fhir_id,sistema_origem)
  SELECT p_paciente,usuario,unidade,p.especialidade,ancora_validada,p_cid10,'doenca',lado_catalogo,
    p_status,sigilo,p_inicio,'fhir',p_fhir_id,sistema_importacao FROM public.perfis AS p WHERE p.id=usuario
    ON CONFLICT DO NOTHING RETURNING id INTO novo;
  IF novo IS NULL THEN
    SELECT a.* INTO existente FROM public.achados AS a WHERE a.unidade_id=unidade AND a.sistema_origem=sistema_importacao
      AND a.origem='fhir' AND a.fhir_id=p_fhir_id;
    IF existente.id IS NULL OR existente.paciente_id<>p_paciente THEN
      INSERT INTO public.auditoria(autor_id,unidade_id,paciente_id,acao) VALUES(usuario,unidade,NULL,'acesso_negado');
      RETURN NULL;
    END IF;
    novo:=existente.id;
  END IF;
  INSERT INTO public.auditoria(autor_id,unidade_id,paciente_id,acao)
    VALUES(usuario,unidade,p_paciente,'importar_condicao_fhir');
  RETURN novo;
END
$$;
REVOKE ALL ON FUNCTION public.importar_condicao_fhir(uuid,uuid,text,text,jsonb,public.status_achado,date,text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.importar_condicao_fhir(uuid,uuid,text,text,jsonb,public.status_achado,date,text) TO authenticated;

CREATE OR REPLACE FUNCTION public.importar_evento_fhir(
  p_importacao uuid,p_paciente uuid,p_fhir_id text,p_tipo text,p_data timestamptz,
  p_codigo text,p_descricao text,p_valor text
)
RETURNS void LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = ''
AS $$
DECLARE usuario uuid:=auth.uid(); unidade uuid:=public.minha_unidade(); existente public.eventos_clinicos; sistema_importacao text;
BEGIN
  p_fhir_id:=NULLIF(btrim(p_fhir_id),'');
  IF usuario IS NULL OR unidade IS NULL THEN RETURN; END IF;
  SELECT i.sistema_origem INTO sistema_importacao FROM public.importacoes_fhir AS i WHERE i.id=p_importacao
    AND i.autor_id=usuario AND i.unidade_id=unidade AND i.concluido_em IS NULL;
  IF NOT public.eh_admin() OR sistema_importacao IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.vinculos AS v WHERE v.paciente_id=p_paciente AND v.unidade_id=unidade
      AND v.desde<=CURRENT_DATE AND (v.ate IS NULL OR v.ate>CURRENT_DATE)
  ) THEN
    INSERT INTO public.auditoria(autor_id,unidade_id,paciente_id,acao) VALUES(usuario,unidade,NULL,'acesso_negado');
    RETURN;
  END IF;
  IF p_fhir_id IS NULL OR p_tipo IS NULL OR p_tipo NOT IN ('Observation','Encounter') THEN
    RAISE EXCEPTION 'Evento FHIR inválido' USING ERRCODE='22023';
  END IF;
  INSERT INTO public.eventos_clinicos(paciente_id,unidade_id,importacao_id,fhir_id,sistema_origem,
    tipo,data,codigo,descricao,valor)
    VALUES(p_paciente,unidade,p_importacao,p_fhir_id,sistema_importacao,p_tipo,p_data,p_codigo,p_descricao,p_valor)
    ON CONFLICT DO NOTHING RETURNING * INTO existente;
  IF NOT FOUND THEN
    SELECT e.* INTO existente FROM public.eventos_clinicos AS e WHERE e.unidade_id=unidade
      AND e.sistema_origem=sistema_importacao AND e.fhir_id=p_fhir_id;
  END IF;
  IF existente.id IS NULL OR existente.paciente_id<>p_paciente THEN
    INSERT INTO public.auditoria(autor_id,unidade_id,paciente_id,acao) VALUES(usuario,unidade,NULL,'acesso_negado');
    RETURN;
  END IF;
  INSERT INTO public.auditoria(autor_id,unidade_id,paciente_id,acao)
    VALUES(usuario,unidade,p_paciente,'importar_evento_fhir');
END
$$;
REVOKE ALL ON FUNCTION public.importar_evento_fhir(uuid,uuid,text,text,timestamptz,text,text,text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.importar_evento_fhir(uuid,uuid,text,text,timestamptz,text,text,text) TO authenticated;
